#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
vector<int> g[MAXN];             // g[v] = prawi sąsiedzi lewego v
int mR[MAXN];                    // mR[u] = lewy skojarzony z prawym u (0 = wolny)
int vis[MAXN], stamp = 0;        // znacznik odwiedzin z „datą” — bez czyszczenia tablicy

bool kuhn(int v) {
    if (vis[v] == stamp) return false;
    vis[v] = stamp;
    for (int u : g[v])
        if (mR[u] == 0 || kuhn(mR[u])) {   // u wolny albo da się przesadzić jego partnera
            mR[u] = v;
            return true;
        }
    return false;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n1, n2, m;
    cin >> n1 >> n2 >> m;        // lewa strona 1..n1, prawa 1..n2
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        g[a].push_back(b);
    }
    int res = 0;
    for (int v = 1; v <= n1; v++) {
        stamp++;
        if (kuhn(v)) res++;
    }
    cout << res << '\n';
    vector<int> mL(n1 + 1, 0);
    for (int u = 1; u <= n2; u++) if (mR[u]) mL[mR[u]] = u;
    for (int v = 1; v <= n1; v++) if (mL[v]) cout << v << ' ' << mL[v] << '\n';
}

