#include <bits/stdc++.h>
using namespace std;
struct HopcroftKarp {
    int n1, n2;
    vector<vector<int>> g;
    vector<int> mL, mR, dist;
    HopcroftKarp(int n1, int n2) : n1(n1), n2(n2), g(n1 + 1), mL(n1 + 1, 0), mR(n2 + 1, 0), dist(n1 + 1) {}
    void addEdge(int a, int b) { g[a].push_back(b); }
    bool bfs() {
        queue<int> q;
        bool found = false;
        for (int v = 1; v <= n1; v++) {
            if (!mL[v]) { dist[v] = 0; q.push(v); }
            else dist[v] = -1;
        }
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int u : g[v]) {
                int w = mR[u];
                if (!w) found = true;
                else if (dist[w] == -1) { dist[w] = dist[v] + 1; q.push(w); }
            }
        }
        return found;
    }
    bool dfs(int v) {
        for (int u : g[v]) {
            int w = mR[u];
            if (!w || (dist[w] == dist[v] + 1 && dfs(w))) { mL[v] = u; mR[u] = v; return true; }
        }
        dist[v] = -1;                      // ślepy zaułek w tej fazie
        return false;
    }
    int maxMatching() {
        int res = 0;
        while (bfs())
            for (int v = 1; v <= n1; v++)
                if (!mL[v] && dfs(v)) res++;
        return res;
    }
};
int main() {
    int n1, n2, m;
    cin >> n1 >> n2 >> m;
    HopcroftKarp hk(n1, n2);
    for (int i = 0; i < m; i++) { int a, b; cin >> a >> b; hk.addEdge(a, b); }
    cout << hk.maxMatching() << '\n';
}

