#include <bits/stdc++.h>
using namespace std;
struct Dinic {
    struct Edge { int to; long long cap; };
    vector<Edge> e;                    // krawędź i oraz odwrotna i^1 leżą obok siebie
    vector<vector<int>> g;
    vector<int> level, it;
    Dinic(int n) : g(n + 1), level(n + 1), it(n + 1) {}
    int addEdge(int a, int b, long long c) {
        g[a].push_back(e.size()); e.push_back({b, c});
        g[b].push_back(e.size()); e.push_back({a, 0});    // krawędź odwrotna, przepustowość 0
        return e.size() - 2;                              // numer krawędzi „w przód”
    }
    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int id : g[v])
                if (e[id].cap > 0 && level[e[id].to] == -1) {
                    level[e[id].to] = level[v] + 1;
                    q.push(e[id].to);
                }
        }
        return level[t] != -1;
    }
    long long dfs(int v, int t, long long f) {
        if (v == t) return f;
        for (int& i = it[v]; i < (int)g[v].size(); i++) {
            int id = g[v][i], u = e[id].to;
            if (e[id].cap > 0 && level[u] == level[v] + 1) {
                long long d = dfs(u, t, min(f, e[id].cap));
                if (d > 0) {
                    e[id].cap -= d;
                    e[id ^ 1].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    long long maxflow(int s, int t) {
        long long flow = 0;
        while (bfs(s, t)) {
            fill(it.begin(), it.end(), 0);
            while (long long f = dfs(s, t, LLONG_MAX)) flow += f;
        }
        return flow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;                     // źródło = 1, ujście = n
    Dinic d(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        long long c;
        cin >> a >> b >> c;            // krawędź skierowana a -> b o przepustowości c
        d.addEdge(a, b, c);
    }
    cout << d.maxflow(1, n) << '\n';
}

