#include <bits/stdc++.h>
using namespace std;
int main() {
    int n, m;
    cin >> n >> m;
    vector<int> to, head(n + 1, -1), nxt;
    vector<long long> cap;
    auto add = [&](int a, int b, long long c) {
        to.push_back(b); cap.push_back(c); nxt.push_back(head[a]); head[a] = to.size() - 1;
        to.push_back(a); cap.push_back(0); nxt.push_back(head[b]); head[b] = to.size() - 1;
    };
    for (int i = 0; i < m; i++) { int a, b; long long c; cin >> a >> b >> c; add(a, b, c); }
    int s = 1, t = n;
    long long flow = 0;
    while (true) {
        vector<int> pe(n + 1, -1);
        vector<bool> vis(n + 1, false);
        queue<int> q; q.push(s); vis[s] = true;
        while (!q.empty() && !vis[t]) {
            int v = q.front(); q.pop();
            for (int e = head[v]; e != -1; e = nxt[e])
                if (cap[e] > 0 && !vis[to[e]]) { vis[to[e]] = true; pe[to[e]] = e; q.push(to[e]); }
        }
        if (!vis[t]) break;
        long long f = LLONG_MAX;
        for (int v = t; v != s; v = to[pe[v] ^ 1]) f = min(f, cap[pe[v]]);
        for (int v = t; v != s; v = to[pe[v] ^ 1]) { cap[pe[v]] -= f; cap[pe[v] ^ 1] += f; }
        flow += f;
    }
    cout << flow << '\n';
}

