using namespace std;
long long stoerWagner(vector<vector<long long>> w) {
    int n = w.size();
    long long best = LLONG_MAX;
    vector<bool> merged(n, false);
    for (int phase = n; phase > 1; phase--) {
        vector<long long> a(n, 0);
        vector<bool> added(n, false);
        int prev = -1;
        for (int i = 0; i < phase; i++) {
            int sel = -1;
            for (int j = 0; j < n; j++)
                if (!merged[j] && !added[j] && (sel == -1 || a[j] > a[sel])) sel = j;
            added[sel] = true;
            if (i == phase - 1) {
                best = min(best, a[sel]);             // przekrój „ostatni vs reszta”
                for (int j = 0; j < n; j++) { w[prev][j] += w[sel][j]; w[j][prev] = w[prev][j]; }
                merged[sel] = true;                   // sklejamy sel z prev
            } else {
                prev = sel;
                for (int j = 0; j < n; j++) a[j] += w[sel][j];
            }
        }
    }
    return best;
}
