using namespace std;
struct MCMF {
    struct Edge { int to; long long cap, cost; };
    vector<Edge> e;
    vector<vector<int>> g;
    vector<long long> dist;
    vector<int> pe;
    vector<bool> inq;
    MCMF(int n) : g(n + 1), dist(n + 1), pe(n + 1), inq(n + 1) {}
    void addEdge(int a, int b, long long cap, long long cost) {
        g[a].push_back(e.size()); e.push_back({b, cap, cost});
        g[b].push_back(e.size()); e.push_back({a, 0, -cost});   // odwrotna: koszt ujemny!
    }
    bool spfa(int s, int t) {                                   // najtańsza ścieżka w sieci residualnej
        fill(dist.begin(), dist.end(), LLONG_MAX);
        deque<int> q;
        dist[s] = 0;
        q.push_back(s);
        inq[s] = true;
        while (!q.empty()) {
            int v = q.front(); q.pop_front();
            inq[v] = false;
            for (int id : g[v]) {
                const Edge& ed = e[id];
                if (ed.cap > 0 && dist[v] + ed.cost < dist[ed.to]) {
                    dist[ed.to] = dist[v] + ed.cost;
                    pe[ed.to] = id;
                    if (!inq[ed.to]) { inq[ed.to] = true; q.push_back(ed.to); }
                }
            }
        }
        return dist[t] != LLONG_MAX;
    }
    pair<long long, long long> run(int s, int t, long long maxf = LLONG_MAX) {   // (przepływ, koszt)
        long long flow = 0, cost = 0;
        while (flow < maxf && spfa(s, t)) {
            long long f = maxf - flow;
            for (int v = t; v != s; v = e[pe[v] ^ 1].to) f = min(f, e[pe[v]].cap);
            for (int v = t; v != s; v = e[pe[v] ^ 1].to) {
                e[pe[v]].cap -= f;
                e[pe[v] ^ 1].cap += f;
            }
            flow += f;
            cost += f * dist[t];
        }
        return {flow, cost};
    }
};

