    pair<long long, long long> run(int s, int t) {
        long long flow = 0, cost = 0;
        const long long INF = LLONG_MAX / 4;
        while (true) {
            fill(dist.begin(), dist.end(), INF);
            priority_queue<pair<long long,int>, vector<pair<long long,int>>, greater<>> pq;
            dist[s] = 0; pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (d > dist[v]) continue;
                for (int id : g[v]) {
                    const Edge& ed = e[id];
                    long long nd = d + ed.cost + h[v] - h[ed.to];       // koszt zredukowany >= 0
                    if (ed.cap > 0 && nd < dist[ed.to]) { dist[ed.to] = nd; pe[ed.to] = id; pq.push({nd, ed.to}); }
                }
            }
            if (dist[t] == INF) break;
            for (int v = 0; v <= n; v++) if (dist[v] < INF) h[v] += dist[v];
            long long f = INF;
            for (int v = t; v != s; v = e[pe[v] ^ 1].to) f = min(f, e[pe[v]].cap);
            for (int v = t; v != s; v = e[pe[v] ^ 1].to) { e[pe[v]].cap -= f; e[pe[v] ^ 1].cap += f; }
            flow += f;
            cost += f * (h[t] - h[s]);
        }
        return {flow, cost};
    }
};
