    int n, m;
    cin >> n >> m;
    MCMFDijkstra f(n);
    for (int i = 0; i < m; i++) { int a, b; long long c, w; cin >> a >> b >> c >> w; f.addEdge(a, b, c, w); }
    auto [flow, cost] = f.run(1, n);
    cout << flow << ' ' << cost << '\n';
}

